<script lang="ts">
 import {languageOverrides} from "./localization";
 import type {Project} from './model';import type {AdministrationDocument} from './administration-schema';import {displayDate} from './date-format';import {D,money} from './engine';import {translator} from './i18n';
 export let project:Project;export let doc:AdministrationDocument;
 $:t=translator(project.settings.language,$languageOverrides);$:records=movements();
 function movements(){if(doc.state!=='applied')return [];const before=JSON.parse(doc.before||'{}'),after=JSON.parse(doc.after||'{}'),rows:{kind:string;account:string;service:string;date:string;value:string}[]=[];
  const add=(kind:string,account:string,service:string,date:string,value:string)=>rows.push({kind,account,service,date,value});
  if(doc.imported){
   if(doc.kind==='service-charges'){for(const row of doc.rows){const snapshot=project.snapshots.find(s=>s.account_id===row.account_id&&s.period===doc.period);if(snapshot){for(const line of snapshot.lines)add(t('Сохранённое начисление','Calcul păstrat'),row.account_id,line.service_id,doc.date,line.amount);if(!D(snapshot.adjustment).isZero())add(t('Сохранённая корректировка','Ajustare păstrată'),row.account_id,'',doc.date,snapshot.adjustment);}}}
   else if(doc.kind==='charge-corrections')for(const row of doc.rows)add(t('Исходная корректировка','Ajustare sursă'),row.account_id,row.service_id,doc.date,row.amount);
   else if(doc.kind==='citizen-changes'){for(const [key,value] of Object.entries(doc.person_attributes))if(value)add(key,'','',doc.date,value);for(const row of doc.rows)add(t('Состав семьи','Componența familiei'),'','',doc.date,(project.reference_catalogs.citizens?.find(c=>c.id===row.relative_id)?.name||row.relative_id)+' · '+(row.active?t('Входит','Membru'):t('Не входит','Nu este membru')));}
   return rows;
  }
  if(after.snapshots){const amounts=(snapshots:Project['snapshots'])=>{const map=new Map<string,ReturnType<typeof D>>();for(const snapshot of snapshots||[])for(const line of snapshot.lines){const key=snapshot.account_id+'|'+line.service_id;map.set(key,(map.get(key)||D(0)).plus(line.amount));}return map;};const a=amounts(after.snapshots),b=amounts(before.snapshots);for(const key of new Set([...a.keys(),...b.keys()])){const delta=(a.get(key)||D(0)).minus(b.get(key)||0);if(!delta.isZero()){const [account,service]=key.split('|');add(t('Начисление','Calcul'),account,service,doc.date,money(delta,project));}}
   const grouped=(shares:Project['service_accounting']['adjustments'])=>{const map=new Map<string,ReturnType<typeof D>>();for(const share of shares||[]){const key=share.account_id+'|'+share.service_id;map.set(key,(map.get(key)||D(0)).plus(share.amount));}return map;};const x=grouped(after.shares),y=grouped(before.shares);for(const key of new Set([...x.keys(),...y.keys()])){const delta=(x.get(key)||D(0)).minus(y.get(key)||0);if(!delta.isZero()){const [account,service]=key.split('|');add(t('Корректировка / льгота / пеня','Ajustare / facilitate / penalitate'),account,service,doc.date,money(delta,project));}}
  }else if(doc.kind==='citizen-changes'){const a=after.citizens?.[0],b=before.citizens?.[0];if(a&&b){if(a.name!==b.name)add(t('ФИО','Nume'),'','',doc.date,b.name+' → '+a.name);for(const key of new Set([...Object.keys(a.attributes),...Object.keys(b.attributes)]))if(a.attributes[key]!==b.attributes[key])add(key,'','',doc.date,(b.attributes[key]||'—')+' → '+(a.attributes[key]||'—'));}}
  else for(const row of doc.rows)add(doc.kind==='building-services'?t('Услуга здания','Serviciu clădire'):doc.kind==='grant-benefits'?t('Назначение льготы','Atribuire facilitate'):t('Прекращение льготы','Încetare facilitate'),row.account_id,row.service_id,row.effective_from,doc.kind==='building-services'?(row.active?t('Подключена','Conectat'):t('Отключена','Deconectat')):doc.kind==='grant-benefits'?(row.method==='percent'?row.rate+'%':row.amount+' MDL'):row.benefit_id);
  return rows;
 }
</script>
<div class="movements"><p>{doc.state==='applied'?t('Движения проведённого документа','Înregistrările documentului aplicat'):t('Документ не проведён. Движений нет.','Documentul nu este aplicat. Nu există înregistrări.')} · №{doc.number}</p><div class="table-wrap"><table><thead><tr><th>{t('Вид движения','Tip înregistrare')}</th><th>{t('Лицевой счёт','Cont personal')}</th><th>{t('Услуга','Serviciu')}</th><th>{t('Дата','Data')}</th><th>{t('Изменение','Modificare')}</th></tr></thead><tbody>{#each records as r}<tr><td>{r.kind}</td><td>{project.accounts.find(a=>a.id===r.account)?.number||''}</td><td>{project.services.find(s=>s.id===r.service)?.name[project.settings.language]||''}</td><td>{displayDate(r.date,project)}</td><td>{r.value}</td></tr>{/each}</tbody></table></div></div>
<style>.movements{padding:16px;display:flex;flex-direction:column;gap:12px}</style>
